<?php
require __DIR__ . '/../../app/admin/bootstrap.php';$q=mb_substr(trim($_GET['search']??''),0,100);$params=['%'.$q.'%','%'.$q.'%'];$where="u.role='user' AND (u.fullname LIKE ? OR u.username LIKE ?)";
$total=(int)db_run('SELECT COUNT(*) total FROM users u WHERE '.$where,$params)->get_result()->fetch_assoc()['total'];$pages=max(1,(int)ceil($total/20));$page=max(1,min($pages,(int)($_GET['page']??1)));
$rows=db_run('SELECT u.id,u.username,u.fullname,u.email,u.phone,u.address,u.created_at,(SELECT COUNT(*) FROM orders o WHERE o.user_id=u.id) orders_count FROM users u WHERE '.$where.' ORDER BY u.id DESC LIMIT 20 OFFSET ?',array_merge($params,[($page-1)*20]))->get_result()->fetch_all(MYSQLI_ASSOC);admin_open('Khách hàng','Thông tin liên hệ và số đơn của khách có tài khoản.');
?>
<form method="get" class="d-flex gap-2 mb-4" style="max-width:500px"><label for="search" class="visually-hidden">Tìm khách hàng</label><input id="search" class="form-control" name="search" value="<?= e($q) ?>" placeholder="Tên hoặc tài khoản"><button class="btn btn-dark">Tìm</button></form><div class="table-responsive"><table class="table"><thead><tr><th>Tài khoản</th><th>Họ tên</th><th>Email</th><th>Điện thoại</th><th>Địa chỉ</th><th>Số đơn</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['username']) ?></td><td><?= e($r['fullname']) ?></td><td><?= e($r['email']) ?></td><td><?= e($r['phone']) ?></td><td><?= e($r['address']) ?></td><td><?= (int)$r['orders_count'] ?></td></tr><?php endforeach ?></tbody></table></div>
<?php if($pages>1): ?><nav class="shop-pagination" aria-label="Phân trang khách hàng"><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++): ?><a href="?<?= e(http_build_query(['search'=>$q,'page'=>$i])) ?>" <?= $page===$i?'aria-current="page"':'' ?>><?= $i ?></a><?php endfor ?></nav><?php endif;admin_close() ?>
